css:
.p19-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p19-page > .deck { grid-row: 2; align-self: center; }
.p19-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p19-top:empty { display: none; }
.p19-strip { --p19-sh: 9rem; }
.p19-strip--b { --p19-sh: 4.5rem; }
.p19-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p19-sh)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p19-strip { --p19-sh: 17rem; } .p19-strip--b { --p19-sh: 6rem; } }
@media (max-width: 21.25rem) { .p19-strip { --p19-sh: 22rem; } .p19-strip--b { --p19-sh: 7rem; } }
.p19-win .deck-card__head { margin-top: 0; }
.p19-face { gap: var(--s-2); }
.p19-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; grid-auto-rows: min-content; gap: var(--s-3); align-content: start; padding-block: var(--s-1) var(--s-2); border-bottom: var(--w1) solid var(--rule); }
.p19-msg { flex: none; display: grid; gap: var(--s-2); }
.p19-msg:empty { display: none; }
.p19-foot { flex: none; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--s-2); }
.dialog__foot.p19-foot2 { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); }
.p19-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -1); }
.p19-area { position: relative; }
.p19-count { position: absolute; right: var(--s-2); bottom: var(--s-1); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); pointer-events: none; background: var(--white); padding-inline: var(--s-1); }
.p19-count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.textarea.p19-ta { min-height: 4rem; padding-bottom: 1.375rem; resize: none; }
.p19-pair { display: grid; grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr)); gap: var(--s-3); align-items: start; }
.p19-pair .field { grid-template-columns: minmax(0, 1fr); }
.p19-pair .select { height: auto; min-width: 0; padding-block: var(--s-2); }
.p19-pair .select > span { min-width: 0; flex: 1 1 auto; overflow: hidden; overflow-wrap: anywhere; }
.p19-pair .select .motive { display: flex; max-width: 100%; }
.p19-pair + .menu { margin-top: calc(var(--s-2) * -1); }
.p19-full { grid-column: 1 / -1; }
.textarea.p19-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p19-tipw { position: relative; display: flex; min-width: 0; }
.p19-tipw > .btn { flex: 1 1 auto; width: 100%; }
.p19-tip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.p19-win .hint { font-size: var(--fs-small); }
.p19-fade { opacity: 0.5; }
.p19-pressed { border-width: var(--w2); border-color: var(--ink); text-decoration: underline; text-underline-offset: 0.25em; }

.dialog.p19-dlg { max-height: 100%; }
.dialog__foot.p19-foot3 { flex-direction: column; }
.dialog__foot.p19-foot3 > * { flex: none; }
.p19-dlg .dialog__body p + p { color: var(--muted); }
.p19-dlg .banner { padding-inline: var(--s-3); }
.p19-dlg .dialog__foot .p19-tipw { position: relative; }
.p19-dtip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }

.p19-list { display: grid; gap: var(--s-2); }
.p19-opt { width: 100%; text-align: start; border: 0; background: var(--white); color: var(--ink); font: inherit; cursor: pointer; border-radius: var(--r); }
.p19-opt .rec__title, .p19-opt .rec__sub { display: block; }
.p19-opt .rec__sub { color: var(--muted); }
.p19-pressed { outline: var(--w2) solid var(--ink); outline-offset: calc(var(--w2) * -1); }
.p19-opt[aria-disabled="true"] { --frame-color: var(--c-disabled-border); color: var(--c-disabled-text); cursor: not-allowed; }
.p19-opt[aria-disabled="true"] .rec__sub { color: var(--c-disabled-text); }
.p19-opt .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p19-opt .rec__value { grid-area: value; align-self: center; }
.p19-tipbox { position: relative; }
.p19-tipbox .tip { position: absolute; z-index: 30; top: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.p19-lead { min-width: 1.25rem; justify-content: center; }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.deck__stack:has(> .p19-win) { width: min(var(--card-max), calc(100cqw - 2rem)); height: auto; }
.deck__stack:has(> .p19-win) ~ .deck__controls { display: none; }
.p19-win { position: relative; left: auto; bottom: auto; width: 100%; height: auto; min-height: var(--card-min); max-height: calc(100cqh - 2rem - var(--p19-win-off, 0rem)); display: flex; flex-direction: column; }
.p19-win .deck-card__face { position: relative; inset: auto; flex: 1 1 auto; min-height: 0; }
.p19-win [class*="-body"], .p19-win .deck-card__scroll { scrollbar-width: thin; scrollbar-color: var(--line) var(--white); }
.p19-strip { --p19-win-off: 9.5rem; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p19-strip { --p19-win-off: 19.5rem; } }
@media (max-width: 21.25rem) { .p19-strip { --p19-win-off: 29.5rem; } }
.p19-strip.p19-strip--b { --p19-win-off: 5.5rem; }
@media (max-width: 21.25rem) { .p19-strip.p19-strip--b { --p19-win-off: 8rem; } }

.p19-dlg .dialog__foot:has(.p19-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p19-dlg .dialog__foot .p19-tipw { display: contents; }
.p19-dlg .dialog__foot .p19-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p19-dlg .dialog__head { flex-wrap: wrap; }
  .p19-dlg .dialog__head > .ibtn { order: -1; margin-inline-start: auto; }
  .p19-dlg .dialog__title { flex: 1 1 100%; }
}
@media (max-width: 21.25rem) { .scrim { padding: var(--s-3); } }

.p19-tipbox .tip { position: static; margin-top: var(--s-1); width: auto; max-width: 100%; }

.p19-sw { display: grid; gap: var(--s-2); }
.p19-sw .swatches { max-width: calc(6 * var(--hit) + 5 * var(--s-2)); }
.p19-swname { display: flex; align-items: center; gap: var(--s-2); min-height: var(--s-4); margin: 0; }
.p19-swname .mdot { width: 1rem; height: 1rem; }
.p19-hint { margin: 0; color: var(--muted); font-size: var(--fs-cap); line-height: var(--lh-cap); }
.swatch:disabled { cursor: not-allowed; }
.swatch:disabled::before { border-color: var(--c-disabled-border); }
.p19-opt .mdot { width: 1rem; height: 1rem; }
.p19-opt[aria-disabled="true"] .mdot { border-color: var(--c-disabled-border); }
